CREATE TABLE "massage_content" (
	"massage_id" text PRIMARY KEY NOT NULL,
	"tagline" text,
	"description" jsonb NOT NULL,
	"body_visual_key" text,
	"body_visual_alt" text,
	"for_whom" jsonb NOT NULL,
	"expectations" jsonb NOT NULL,
	"safety" jsonb NOT NULL,
	"steps" jsonb,
	"booking_cta" jsonb NOT NULL,
	"seo_phrases" text[] NOT NULL,
	"related_massage_ids" text[] NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
